"""Shared locations. Everything generated by the experiments lives under experiments/work/."""
import os
from pathlib import Path
EXP = Path(__file__).resolve().parent
ROOT = EXP.parent
WORK = EXP / os.environ.get('LIWSA_WORK', 'work')   # --quick uses a separate folder (work_quick)
SEEDS, RESULTS, ANALYSIS, CLASSES = (WORK / d for d in ('seeds', 'results', 'analysis', 'classes'))
DAX = ROOT / 'config' / 'dax'
for d in (WORK, SEEDS, RESULTS, ANALYSIS, CLASSES):
    d.mkdir(parents=True, exist_ok=True)
